function pairsToTarget(nums: number[], k: number): number {
  const used = new Array(nums.length).fill(false);
  let pairs = 0;
  for (let i = 0; i < nums.length; i++) {
    if (used[i]) continue;
    for (let j = i + 1; j < nums.length; j++) {
      if (!used[j] && nums[i] + nums[j] === k) {
        used[i] = used[j] = true;
        pairs++;
        break;
      }
    }
  }
  return pairs;
}

