function pairsToTarget(nums: number[], k: number): number {
  const a = [...nums].sort((x, y) => x - y);
  let lo = 0, hi = a.length - 1, pairs = 0;
  while (lo < hi) {
    const s = a[lo] + a[hi];
    if (s === k) { pairs++; lo++; hi--; }
    else if (s < k) lo++;
    else hi--;
  }
  return pairs;
}

