function pairsToTarget(nums: number[], k: number): number {
  const waiting = new Map<number, number>();
  let pairs = 0;
  for (const v of nums) {
    const need = k - v;
    const c = waiting.get(need) ?? 0;
    if (c > 0) {
      waiting.set(need, c - 1);
      pairs++;
    } else {
      waiting.set(v, (waiting.get(v) ?? 0) + 1);
    }
  }
  return pairs;
}

